parameters.text:
=Research this inbound lead and produce the three-paragraph brief.

Lead name: {{ $json.body.name || 'unknown' }}
Work email: {{ $json.body.email || 'unknown' }}
Company name: {{ $json.body.company || 'unknown' }}
Email domain: {{ ($json.body.email || '').split('@')[1] || 'unknown' }}

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "score": {
      "type": "integer",
      "minimum": 0,
      "maximum": 100,
      "description": "Overall ICP fit score out of 100"
    },
    "reasoning": {
      "type": "string",
      "description": "Two to three sentences citing which rubric dimensions drove the score"
    },
    "data_confidence": {
      "type": "string",
      "enum": ["high", "medium", "low"],
      "description": "How well sourced the underlying research was"
    }
  },
  "required": ["score", "reasoning", "data_confidence"]
}

parameters.text:
